import pandas as pd
import numpy as np

# Load data
crime_df = pd.read_csv('chunks_csv/moran_local_no2crime_crime_first_half_2021.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Build symmetric adjacency dictionary
adj_dict = {}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b not in adj_dict:
        adj_dict[b] = set()
    adj_dict[b].add(n)
    if n not in adj_dict:
        adj_dict[n] = set()
    adj_dict[n].add(b)

# Ensure all crime boroughs are in adj_dict
all_boroughs = set(crime_df['borough'])
for b in all_boroughs:
    if b not in adj_dict:
        adj_dict[b] = set()

# Impute missing value
if crime_df['value'].isnull().any():
    missing_row = crime_df[crime_df['value'].isnull()]
    missing_borough = missing_row['borough'].iloc[0]
    neighbors = adj_dict[missing_borough]
    neighbor_rates = crime_df[crime_df['borough'].isin(neighbors)]['value'].dropna()
    if len(neighbor_rates) > 0:
        impute_value = neighbor_rates.mean()
    else:
        impute_value = crime_df['value'].dropna().mean()
    crime_df.loc[crime_df['borough'] == missing_borough, 'value'] = impute_value

# Compute global mean
global_mean = crime_df['value'].mean()
crime_series = crime_df.set_index('borough')['value']

# Calculate observed S_i for all boroughs
observed_S = {}
for borough in crime_series.index:
    z_i = crime_series[borough] - global_mean
    neighbors = adj_dict[borough]
    sum_z_neighbors = 0
    for n in neighbors:
        if n in crime_series.index:
            sum_z_neighbors += (crime_series[n] - global_mean)
    S_i = z_i * sum_z_neighbors
    observed_S[borough] = S_i

# Identify candidates (S_i > 0)
candidates = [b for b, s in observed_S.items() if s > 0]
observed_S_candidates = {b: observed_S[b] for b in candidates}

# Permutation tests
n_perm = 999
counts = {candidate: 0 for candidate in candidates}
borough_list = crime_series.index.tolist()
crime_values = crime_series.values

for _ in range(n_perm):
    shuffled_values = np.random.permutation(crime_values)
    shuffled_series = pd.Series(shuffled_values, index=borough_list)
    for candidate in candidates:
        z_i_perm = shuffled_series[candidate] - global_mean
        sum_z_neighbors_perm = 0
        for neighbor in adj_dict[candidate]:
            if neighbor in shuffled_series.index:
                sum_z_neighbors_perm += (shuffled_series[neighbor] - global_mean)
        S_i_perm = z_i_perm * sum_z_neighbors_perm
        if S_i_perm >= observed_S_candidates[candidate]:
            counts[candidate] += 1

# Calculate p-values and classify significant boroughs
significant_results = []
for candidate in candidates:
    p_value = (counts[candidate] + 1) / (n_perm + 1)
    if p_value < 0.05:
        if crime_series[candidate] > global_mean:
            classification = "HH"
        else:
            classification = "LL"
        significant_results.append((candidate, classification, p_value))

# Output
print(f"data_points_used = {len(crime_df)}")
if significant_results:
    result_str = ", ".join([f"{res[0]} ({res[1]}, p-value={res[2]:.4f})" for res in significant_results])
    print(f"FINAL ANSWER: {result_str}")
else:
    print("FINAL ANSWER: none")
